// Package urfave generates a github.com/urfave/cli/v3 command tree from an
// OpenCLI model.
//
// The generated file declares a Handlers interface with one method per
// runnable command and a New function that builds the command tree wired to
// a Handlers implementation. Positional arguments and flag values are checked
// with the github.com/angrifel/opencligen/clirt runtime package.
package urfave

import (
	"bytes"
	"encoding/json"
	"fmt"
	"go/format"
	"go/token"
	"slices"
	"strconv"
	"strings"
	"time"
	"unicode"

	"github.com/angrifel/opencligen/spec"
)

// Options configure the generated code.
type Options struct {
	Package string // package name of the generated file; "cli" by default
	Source  string // document name mentioned in the generated header

	// Lenient turns OpenCLI features that urfave/cli cannot express into
	// warnings and generates the closest approximation instead.
	Lenient bool
}

const runtimeImport = "github.com/angrifel/opencligen/clirt"

// Generate renders the model as a Go source file. It returns warnings, and
// a *spec.Error when the model uses features urfave/cli cannot express.
func Generate(m *spec.Model, opts Options) ([]byte, []spec.Diagnostic, error) {
	if opts.Package == "" {
		opts.Package = "cli"
	}
	if !token.IsIdentifier(opts.Package) {
		return nil, nil, fmt.Errorf("invalid package name %q", opts.Package)
	}
	g := &generator{model: m, opts: opts, methods: map[string]string{}}
	g.checkConventions()

	var tree bytes.Buffer
	g.out = &tree
	g.command(m.Root)

	var errs, warns []spec.Diagnostic
	for _, d := range g.diags {
		if d.Severity == spec.SeverityWarning {
			warns = append(warns, d)
		} else {
			errs = append(errs, d)
		}
	}
	if len(errs) > 0 {
		return nil, warns, &spec.Error{Diagnostics: errs}
	}

	var file bytes.Buffer
	g.out = &file
	g.header(tree.Bytes())

	src, err := format.Source(file.Bytes())
	if err != nil {
		return nil, warns, fmt.Errorf("formatting generated code: %w", err)
	}
	return src, warns, nil
}

type handler struct {
	method string
	path   string
}

type generator struct {
	model    *spec.Model
	opts     Options
	out      *bytes.Buffer
	diags    []spec.Diagnostic
	handlers []handler
	methods  map[string]string // method name -> command path

	needTime    bool
	needRuntime bool
}

func (g *generator) p(format string, args ...any) {
	fmt.Fprintf(g.out, format, args...)
}

// unsupported reports a feature urfave/cli cannot express: an error, or a
// warning in lenient mode. It returns true when generation may continue with
// an approximation.
func (g *generator) unsupported(ptr, format string, args ...any) bool {
	sev := spec.SeverityError
	if g.opts.Lenient {
		sev = spec.SeverityWarning
	}
	g.diags = append(g.diags, g.model.Diagnostic(sev, ptr, format, args...))
	return g.opts.Lenient
}

func (g *generator) fail(ptr, format string, args ...any) {
	g.diags = append(g.diags, g.model.Diagnostic(spec.SeverityError, ptr, format, args...))
}

func (g *generator) checkConventions() {
	switch sep := g.model.Conventions.OptionSeparator; sep {
	case " ", "=":
		// urfave/cli accepts both "--name value" and "--name=value".
	default:
		g.unsupported("/conventions/optionSeparator",
			"option separator %q is not supported by urfave/cli, which only accepts \" \" and \"=\"", sep)
	}
}

func (g *generator) header(tree []byte) {
	src := g.opts.Source
	if src == "" {
		src = "an OpenCLI description"
	}
	g.p("// Code generated by opencligen from %s. DO NOT EDIT.\n\n", src)
	g.p("package %s\n\nimport (\n", g.opts.Package)
	if len(g.handlers) > 0 {
		g.p("%q\n", "context")
	}
	if g.needTime {
		g.p("%q\n", "time")
	}
	g.p("\n%q\n", "github.com/urfave/cli/v3")
	if g.needRuntime {
		g.p("\n%q\n", runtimeImport)
	}
	g.p(")\n\n")

	g.p("// Handlers implements the commands described in %s.\n", src)
	g.p("type Handlers interface {\n")
	for _, h := range g.handlers {
		g.p("// %s runs `%s`.\n", h.method, h.path)
		g.p("%s(ctx context.Context, cmd *cli.Command) error\n", h.method)
	}
	g.p("}\n\n")
	g.p("// New returns the %s command tree wired to h.\n", g.model.Root.Name)
	g.p("func New(h Handlers) *cli.Command {\nreturn ")
	g.out.Write(tree)
	g.p("\n}\n")
}

// builtin reports whether urfave/cli already provides an option: --help
// everywhere, and --version on the root when info.version is set. Other
// options may still claim -h or -v; urfave/cli then drops those short
// aliases from its own flags.
func (g *generator) builtin(c *spec.Command, o *spec.Option) bool {
	return slices.Contains(o.Names, "help") ||
		(c.IsRoot() && g.model.Info.Version != "" && slices.Contains(o.Names, "version"))
}

func (g *generator) command(c *spec.Command) {
	g.p("&cli.Command{\n")
	g.p("Name: %q,\n", c.Name)
	if len(c.Aliases) > 0 {
		g.p("Aliases: %#v,\n", c.Aliases)
	}
	if c.Summary != "" {
		g.p("Usage: %q,\n", c.Summary)
	}
	if len(c.Usage) > 0 {
		g.p("UsageText: %q,\n", strings.Join(c.Usage, "\n"))
	}
	if long := longDescription(c); long != "" {
		g.p("Description: %q,\n", long)
	}
	if c.Category != "" {
		g.p("Category: %q,\n", c.Category)
	}
	if c.IsRoot() {
		if g.model.Info.Version != "" {
			g.p("Version: %q,\n", g.model.Info.Version)
		}
		if g.model.Conventions.GroupOptions {
			g.p("UseShortOptionHandling: true,\n")
		}
	}
	if c.Hidden {
		g.p("Hidden: true,\n")
	}
	if au := c.ArgsUsage(); au != "" {
		g.p("ArgsUsage: %q,\n", au)
	}

	g.checkShadowing(c)
	var flags []*spec.Option
	for _, o := range c.Options {
		if !g.builtin(c, o) {
			flags = append(flags, o)
		}
	}
	if len(flags) > 0 {
		g.p("Flags: []cli.Flag{\n")
		for _, o := range flags {
			g.flag(o)
		}
		g.p("},\n")
	}

	// Register the handler before descending, so Handlers lists parents first.
	method := ""
	if c.Runnable() {
		method = g.method(c)
	}

	if len(c.Commands) > 0 {
		g.p("Commands: []*cli.Command{\n")
		for _, s := range c.Commands {
			g.command(s)
			g.p(",\n")
		}
		g.p("},\n")
	}

	if method != "" {
		g.needRuntime = true
		g.p("Action: func(ctx context.Context, cmd *cli.Command) error {\n")
		g.p("if err := clirt.CheckArgs(cmd, %s); err != nil {\nreturn err\n}\n", g.argSpecs(c.Arguments))
		g.p("return h.%s(ctx, cmd)\n},\n", method)
	}
	g.p("}")
}

// checkShadowing reports options that reuse a name of an inherited recursive
// option. urfave/cli lets the subcommand's flag win but then drops the whole
// inherited flag in that subcommand, so its other names stop working there.
func (g *generator) checkShadowing(c *spec.Command) {
	inherited := c.InheritedOptions()
	for _, o := range c.Options {
		if g.builtin(c, o) {
			continue
		}
		for _, p := range inherited {
			// Redeclaring the same option is fine, and urfave/cli itself
			// handles a subcommand reusing -h or -v of its help and version
			// flags.
			builtinP := slices.Contains(p.Names, "help") ||
				(slices.Contains(p.Names, "version") && g.model.Info.Version != "")
			if builtinP || slices.Equal(o.Names, p.Names) {
				continue
			}
			for _, n := range o.Names {
				if slices.Contains(p.Names, n) {
					g.unsupported(o.Pointer+"/name",
						"%s: option %q reuses the name %q of the recursive option %q; urfave/cli would drop %q entirely in this subcommand",
						c.FullName(), o.Name, n, p.Name, p.Name)
				}
			}
		}
	}
}

// method returns the Handlers method of a runnable command: the x-go-name
// metadata when present, otherwise the command path in CamelCase without
// the root ("Root" for the root itself).
func (g *generator) method(c *spec.Command) string {
	name := ""
	if raw, ok := c.Metadata.Get("x-go-name"); ok {
		if err := json.Unmarshal(raw, &name); err != nil || !token.IsIdentifier(name) || !unicode.IsUpper([]rune(name)[0]) {
			g.fail(c.Pointer+"/metadata", "%s: x-go-name must be an exported Go identifier, got %s", c.FullName(), raw)
			name = ""
		}
	}
	if name == "" {
		name = defaultMethod(c.Path())
	}
	if prev, dup := g.methods[name]; dup {
		g.fail(c.Pointer, "commands %q and %q both map to handler method %s; set x-go-name on one of them", prev, c.FullName(), name)
	}
	g.methods[name] = c.FullName()
	g.handlers = append(g.handlers, handler{method: name, path: c.FullName()})
	return name
}

func defaultMethod(path []string) string {
	if len(path) == 1 {
		return "Root"
	}
	var b strings.Builder
	for _, seg := range path[1:] {
		upper := true
		for _, r := range seg {
			if !unicode.IsLetter(r) && !unicode.IsDigit(r) {
				upper = true
				continue
			}
			if upper {
				r = unicode.ToUpper(r)
				upper = false
			}
			b.WriteRune(r)
		}
	}
	name := b.String()
	if name == "" || unicode.IsDigit(rune(name[0])) {
		name = "Cmd" + name
	}
	return name
}

func longDescription(c *spec.Command) string {
	var parts []string
	// urfave/cli shows Usage (the summary) next to the name, so leave it out
	// when the description starts with it.
	if d := strings.TrimSpace(strings.TrimPrefix(c.Description, c.Summary)); d != "" {
		parts = append(parts, d)
	}
	if c.Interactive {
		parts = append(parts, "This command is interactive.")
	}
	if len(c.Examples) > 0 {
		parts = append(parts, "Examples:\n  "+strings.Join(c.Examples, "\n  "))
	}
	if len(c.ExitCodes) > 0 {
		var b strings.Builder
		b.WriteString("Exit codes:")
		for _, e := range c.ExitCodes {
			fmt.Fprintf(&b, "\n  %d", e.Code)
			if e.Description != "" {
				b.WriteString("  " + e.Description)
			}
		}
		parts = append(parts, b.String())
	}
	if c.Documentation != "" {
		parts = append(parts, "Documentation: "+c.Documentation)
	}
	return strings.Join(parts, "\n\n")
}

// goType is the Go element type of a value type.
var goType = map[spec.Type]string{
	spec.String:   "string",
	spec.Int:      "int",
	spec.Uint:     "uint",
	spec.Float:    "float64",
	spec.Bool:     "bool",
	spec.Duration: "time.Duration",
}

// flagType returns the urfave/cli flag type for a value.
func flagType(v spec.Value) string {
	if v.Type == spec.Bool {
		if v.TakesValue {
			return "StringFlag" // "-flag true"; BoolFlag never consumes an argument
		}
		return "BoolFlag"
	}
	base := map[spec.Type]string{spec.String: "String", spec.Int: "Int", spec.Uint: "Uint", spec.Float: "Float", spec.Duration: "Duration"}[v.Type]
	if v.Multi {
		return base + "SliceFlag"
	}
	return base + "Flag"
}

func (g *generator) flag(o *spec.Option) {
	v := o.Value
	if len(o.ValueNames) > 1 && !g.unsupported(o.Pointer+"/arguments",
		"option %q takes %d arguments per use, which urfave/cli flags cannot express", o.Name, len(o.ValueNames)) {
		return
	}
	if v.Type == spec.Duration {
		g.needTime = true
	}

	g.p("&cli.%s{\n", flagType(v))
	g.p("Name: %q,\n", o.Names[0])
	if len(o.Names) > 1 {
		g.p("Aliases: %#v,\n", o.Names[1:])
	}
	if o.Description != "" {
		g.p("Usage: %q,\n", o.Description)
	}
	if o.Group != "" {
		g.p("Category: %q,\n", o.Group)
	}
	if o.Required {
		g.p("Required: true,\n")
	}
	if o.Hidden {
		g.p("Hidden: true,\n")
	}
	if !o.Recursive {
		g.p("Local: true,\n")
	}
	if v.HasDefault() && (!v.Multi || len(v.Default) > 0) {
		g.p("Value: %s,\n", defaultLiteral(v))
	}
	if check := g.check(o.Name, v); check != "" {
		g.p("Validator: %s,\n", check)
	}
	g.p("},\n")
}

// check returns a validator expression for a flag value, or "".
func (g *generator) check(name string, v spec.Value) string {
	var c string
	switch {
	case v.Type == spec.Bool && v.TakesValue:
		c = fmt.Sprintf("clirt.Bool(%q)", name)
	case len(v.Accepted) > 0:
		c = fmt.Sprintf("clirt.OneOf(%q, %s)", name, quoteAll(v.Accepted))
	case v.HasRange():
		c = between(name, v)
	}
	if c == "" {
		return ""
	}
	g.needRuntime = true
	if v.Multi {
		c = "clirt.Each(" + c + ")"
	}
	return c
}

func between(name string, v spec.Value) string {
	lo, hasLo := boundLiteral(v.Min)
	hi, hasHi := boundLiteral(v.Max)
	return fmt.Sprintf("clirt.Between[%s](%q, %s, %t, %s, %t)", goType[v.Type], name, lo, hasLo, hi, hasHi)
}

// argSpecs renders the clirt.Arg list of a command's positional arguments.
func (g *generator) argSpecs(args []*spec.Argument) string {
	if len(args) == 0 {
		return "nil"
	}
	var b strings.Builder
	b.WriteString("[]clirt.Arg{\n")
	for _, a := range args {
		name := "<" + a.Name + ">"
		fmt.Fprintf(&b, "{Name: %q, Min: %d, Max: %d", name, a.MinCount, a.MaxCount)
		if c := argCheck(name, a.Value); c != "" {
			fmt.Fprintf(&b, ", Check: %s", c)
		}
		b.WriteString("},\n")
	}
	b.WriteString("}")
	return b.String()
}

func argCheck(name string, v spec.Value) string {
	rng := "nil"
	if v.HasRange() {
		rng = between(name, v)
	}
	switch v.Type {
	case spec.String:
		if len(v.Accepted) > 0 {
			return fmt.Sprintf("clirt.OneOf(%q, %s)", name, quoteAll(v.Accepted))
		}
	case spec.Int:
		return fmt.Sprintf("clirt.Int(%q, %s)", name, rng)
	case spec.Uint:
		return fmt.Sprintf("clirt.Uint(%q, %s)", name, rng)
	case spec.Float:
		return fmt.Sprintf("clirt.Float(%q, %s)", name, rng)
	case spec.Bool:
		return fmt.Sprintf("clirt.Bool(%q)", name)
	case spec.Duration:
		return fmt.Sprintf("clirt.Duration(%q)", name)
	}
	return ""
}

func quoteAll(ss []string) string {
	q := make([]string, len(ss))
	for i, s := range ss {
		q[i] = strconv.Quote(s)
	}
	return strings.Join(q, ", ")
}

// goValue renders a model value as a Go literal.
func goValue(v any) string {
	switch x := v.(type) {
	case string:
		return strconv.Quote(x)
	case float64:
		return strconv.FormatFloat(x, 'g', -1, 64)
	case time.Duration:
		return fmt.Sprintf("time.Duration(%d) /* %s */", int64(x), x)
	default:
		return fmt.Sprint(x)
	}
}

func defaultLiteral(v spec.Value) string {
	if v.Type == spec.Bool && v.TakesValue {
		return strconv.Quote(strconv.FormatBool(v.Default[0].(bool)))
	}
	parts := make([]string, len(v.Default))
	for i, d := range v.Default {
		parts[i] = goValue(d)
	}
	if v.Multi {
		return "[]" + goType[v.Type] + "{" + strings.Join(parts, ", ") + "}"
	}
	return parts[0]
}

func boundLiteral(b any) (lit string, set bool) {
	if b == nil {
		return "0", false
	}
	return goValue(b), true
}
